content:
{
 "command": "make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "pattern": "LEDGERLINE_FX_FIXTURES",
 "output_mode": "content"
}

{
 "command": "cat Makefile; cat tests/fxdata.py; ls -R tests | head -30",
 "description": "Inspect Makefile and fixture loader"
}

{
 "command": "sed -n 1,30p docs/testing.md; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Read testing docs and rerun with fixtures env var"
}

{
 "command": "python scripts/gen_fx_fixtures.py 2>&1 | tail -5; git status --short; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Generate FX fixtures and rerun fast tests"
}

{
 "mode": "filter",
 "query": "PSP sandbox region integration tests",
 "max_results": 5
}
